#!/usr/bin/env node
/**
 * Generates the style engine's tables from its one declaration, resources/engine/schema.json.
 *
 * Usage:  node scripts/gen-engine.mjs           write the generated files
 *         node scripts/gen-engine.mjs --check   exit non-zero if any of them is stale
 *
 * The engine used to be kept as four hand-synced copies — the TS emitter, its PHP port, the
 * runtime stylesheet's SCSS maps and the Inspector's section registry — held together only by
 * mirrored tests. Each copy now reads the same generated data, so a control added to the schema
 * reaches all four at once and a hand edit to any of them fails `--check` (and the vitest suite,
 * which calls `render()` directly).
 *
 * What stays hand-written is behaviour, not data: the value builders in vars.ts and
 * ElementStyle.php, and the runtime stylesheet's loops and its `custom` rules.
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve( path.dirname( fileURLToPath( import.meta.url ) ), '..' );

const SCHEMA = 'resources/engine/schema.json';
const BREAKPOINTS = 'resources/design-system/breakpoints.json';

export const OUTPUTS = {
	ts: 'resources/engine/schema.gen.ts',
	php: 'src/Style/Schema.php',
	scss: 'resources/runtime/_engine.scss',
};

const KINDS = [ 'sides', 'inset', 'corners', 'single', 'enum' ];
const FLAGS = [ 'caution', 'niche' ];
const PART_GUARDS = [ 'motion', 'timeline' ];
/**
 * How one control bears on others — the Style Property Graph, kept with the controls so the
 * inspector can hide what is moot and a layout validator can refuse what fights:
 *  - `enables`         the targets only take effect once `from` is set (on the same element)
 *  - `enablesChildren` same, but the targets live on the element's children
 *  - `expands`         the targets refine `from` (min/max of a width, per-axis overflow)
 *  - `writes`          setting `from` also writes the targets
 *  - `conflicts`       `from` overrides or cancels the targets
 *  - `twin`            the two write the same or a confusingly similar CSS property
 */
const RELATION_KINDS = [ 'enables', 'enablesChildren', 'expands', 'writes', 'conflicts', 'twin' ];
/**
 * Categories whose value is a structured object (or a few accepted forms) built by a named builder in
 * vars.ts / ElementStyle.php. Each has a value shape of the same name in schema.json's `valueShapes`.
 */
const BUILT_SHAPES = [ 'boxShadow', 'outline', 'textShadow', 'gradient', 'backgroundLayers', 'image', 'clipPath', 'backdropFilter', 'mask', 'transform', 'content' ];
const RUNTIME_GROUPS = [ 'spacing', 'layout', 'gridChild', 'columns', 'flexChild', 'sceneItem', 'sceneChild', 'effects', 'multi', 'supports', 'custom' ];
/**
 * Groups that place an element inside a Scene. A pseudo-element is never a scene box or a scene
 * item, so these never render on a part.
 */
const PLACEMENT_GROUPS = [ 'sceneItem', 'sceneChild' ];
const SCSS_MAPS = {
	spacing: 'spacing',
	layout: 'layout',
	gridChild: 'grid-child',
	columns: 'columns',
	flexChild: 'flex-child',
	sceneItem: 'scene-item',
	sceneChild: 'scene-child',
	effects: 'effects',
	multi: 'multis',
	supports: 'supported',
};

const HEADER = `GENERATED by scripts/gen-engine.mjs from ${ SCHEMA } — do not edit. Run \`pnpm gen:engine\`.`;

function read( file ) {
	return JSON.parse( fs.readFileSync( path.join( root, file ), 'utf8' ) );
}

/**
 * What a control's value looks like: the shape in `valueShapes` it takes, the token scale its slugs
 * come from, and for an enum the names it accepts. Derived, so a new control is described the moment
 * it is declared.
 */
export function valueShapeOf( c, schema ) {
	const tokens = c.category && ! BUILT_SHAPES.includes( c.category ) && c.category !== 'backgroundLayers' ? { tokens: c.category } : {};
	if ( c.kind === 'enum' ) return { shape: 'enum', values: c.values ?? schema.typeRoles };
	if ( c.kind === 'corners' ) return { shape: 'corners', ...tokens };
	if ( c.kind === 'inset' ) return { shape: 'inset', ...tokens };
	if ( c.kind === 'sides' ) return { shape: c.raw ? 'sidesKeyword' : 'sides', ...tokens };
	if ( BUILT_SHAPES.includes( c.category ) ) return { shape: c.category };
	// The CSS property a plain value is written to, so a caller is told what it is writing.
	const property = c.runtime?.prop ?? c.import?.[ 0 ];
	return { shape: c.category ? 'tokenOrCss' : 'css', ...tokens, ...( property ? { property } : {} ), ...( c.note ? { note: c.note } : {} ) };
}

/** The value shapes with `{ "$ref": "#/name" }` replaced by the shape it names. */
function resolvedShapes( schema ) {
	const shapes = schema.valueShapes ?? {};
	const inline = ( v ) => {
		if ( Array.isArray( v ) ) return v.map( inline );
		if ( v && typeof v === 'object' ) {
			if ( typeof v.$ref === 'string' && v.$ref.startsWith( '#/' ) ) return inline( shapes[ v.$ref.slice( 2 ) ] );
			return Object.fromEntries( Object.entries( v ).map( ( [ k, x ] ) => [ k, inline( x ) ] ) );
		}
		return v;
	};
	return inline( shapes );
}

/** Throws on the mistakes a hand edit to the schema is likely to make. */
export function validate( schema ) {
	const errors = [];
	const sectionIds = new Set( schema.sections.map( ( s ) => s.id ) );
	const seen = { id: new Set(), cls: new Set(), var: new Set() };
	const imported = new Map();

	for ( const c of schema.controls ) {
		for ( const key of [ 'id', 'cls', 'var' ] ) {
			if ( c[ key ] === undefined ) continue;
			if ( seen[ key ].has( c[ key ] ) ) errors.push( `duplicate ${ key } "${ c[ key ] }"` );
			seen[ key ].add( c[ key ] );
		}
		if ( ! /^[a-z][a-zA-Z]*\.[a-zA-Z]+$/.test( c.id ) ) errors.push( `${ c.id }: id must be "family.name"` );
		if ( ! KINDS.includes( c.kind ) ) errors.push( `${ c.id }: unknown kind "${ c.kind }"` );
		if ( c.kind !== 'enum' && ! c.partOnly && ! c.var ) errors.push( `${ c.id }: needs a var` );
		if ( c.partOnly && ( c.var || c.runtime || typeof c.part !== 'object' ) ) {
			// A part-only control never reaches the element, so a var or runtime rule would be dead.
			errors.push( `${ c.id }: a partOnly control takes a part.prop and no var or runtime rule` );
		}
		if ( c.part !== undefined && c.part !== 'special' && ( typeof c.part !== 'object' || ! c.part.prop ) ) {
			errors.push( `${ c.id }: part must be "special" or { prop }` );
		}
		if ( c.part?.guard !== undefined && ! PART_GUARDS.includes( c.part.guard ) ) errors.push( `${ c.id }: unknown part guard "${ c.part.guard }"` );
		if ( ! sectionIds.has( c.section ) ) errors.push( `${ c.id }: unknown section "${ c.section }"` );
		if ( c.flag !== undefined && ! FLAGS.includes( c.flag ) ) errors.push( `${ c.id }: unknown flag "${ c.flag }"` );
		for ( const property of c.import ?? [] ) {
			// The importer resolves a pasted declaration to exactly one control.
			if ( imported.has( property ) ) errors.push( `${ c.id }: CSS property "${ property }" already imports to ${ imported.get( property ) }` );
			imported.set( property, c.id );
		}

		const scoped = c.selectorSuffix !== undefined;
		if ( c.runtime ) {
			if ( ! RUNTIME_GROUPS.includes( c.runtime.group ) ) errors.push( `${ c.id }: unknown runtime group "${ c.runtime.group }"` );
			if ( c.runtime.group !== 'custom' && ! c.runtime.prop ) errors.push( `${ c.id }: runtime rule needs a prop` );
		} else if ( ! scoped && c.kind !== 'enum' && ! c.partOnly ) {
			// A tier-1/2 control with no runtime rule emits a class nothing styles: it looks set
			// in the inspector and does nothing on the page.
			errors.push( `${ c.id }: no runtime rule, and not scoped or enum` );
		}
	}

	for ( const s of schema.sections ) {
		for ( const id of s.also ?? [] ) {
			if ( ! seen.id.has( id ) ) errors.push( `section ${ s.id }: also lists unknown control "${ id }"` );
		}
	}

	for ( const r of schema.relations ?? [] ) {
		if ( ! RELATION_KINDS.includes( r.kind ) ) errors.push( `relation ${ r.from }: unknown kind "${ r.kind }"` );
		for ( const id of [ r.from, ...r.to ] ) {
			if ( ! seen.id.has( id ) ) errors.push( `relation ${ r.kind } ${ r.from }: unknown control "${ id }"` );
		}
	}

	for ( const [ id, suffix ] of Object.entries( schema.parts ?? {} ) ) {
		if ( ! /^[a-z]+$/.test( id ) || ! /^::[a-z-]+$/.test( suffix ) ) errors.push( `part ${ id }: needs a lowercase id and a ::pseudo suffix` );
	}

	for ( const c of schema.controls ) {
		const { shape } = valueShapeOf( c, schema );
		if ( ! schema.valueShapes?.[ shape ] ) errors.push( `${ c.id }: no value shape "${ shape }" in valueShapes` );
	}

	if ( ! schema.typeRoles?.length || schema.typeRoles.some( ( role ) => ! /^[a-z0-9]+$/.test( role ) ) ) {
		errors.push( 'typeRoles must be a non-empty list of lowercase slugs' );
	}

	if ( errors.length ) throw new Error( `${ SCHEMA } is invalid:\n  ${ errors.join( '\n  ' ) }` );
}

/** The emission rule each engine reads — the schema's control minus inspector/runtime data. */
function rule( c ) {
	const r = { attr: c.id, cls: c.cls, kind: c.kind, v: c.var ?? '' };
	for ( const key of [ 'category', 'raw', 'emptyValue', 'prop', 'selectorSuffix', 'partOnly' ] ) {
		if ( c[ key ] !== undefined ) r[ key ] = c[ key ];
	}
	return r;
}

function sectionControls( schema ) {
	const out = {};
	for ( const s of schema.sections ) {
		out[ s.id ] = [ ...schema.controls.filter( ( c ) => c.section === s.id ).map( ( c ) => c.id ), ...( s.also ?? [] ) ];
	}
	return out;
}

/**
 * How a control renders on a part (`::before`/`::after`), or null when it cannot: a library preset
 * (its look is a global class on the element), a rule that is already scoped, or a custom property
 * a keyframe reads. `special` controls are rendered by bespoke code in the emitters.
 */
function partOf( c ) {
	if ( c.kind === 'enum' || c.selectorSuffix !== undefined ) return null;
	if ( c.part !== undefined ) return c.part;
	const rt = c.runtime;
	if ( ! rt?.prop || rt.group === 'custom' || PLACEMENT_GROUPS.includes( rt.group ) ) return null;
	return rt.webkit ? { prop: rt.prop, webkit: true } : { prop: rt.prop };
}

/** `border-radius` → its four corner longhands, in CORNERS order (tl, tr, br, bl). */
export function cornerLonghands( prop ) {
	const [ head, ...rest ] = prop.split( '-' );
	return [ 'top-left', 'top-right', 'bottom-right', 'bottom-left' ].map( ( corner ) => `${ head }-${ corner }-${ rest.join( '-' ) }` );
}

function partTables( schema, breakpoints ) {
	const props = {};
	const special = [];
	const controls = [];
	for ( const c of schema.controls ) {
		const part = partOf( c );
		if ( ! part ) continue;
		controls.push( c.id );
		if ( part === 'special' ) special.push( c.cls );
		else props[ c.cls ] = part;
	}
	const bpMax = {};
	for ( const bp of breakpoints ) bpMax[ schema.breakpoints[ bp.id ] ] = bp.max === null ? '' : `${ bp.max }px`;
	return { props, special, controls, bpMax, bpOrder: breakpoints.map( ( bp ) => schema.breakpoints[ bp.id ] ) };
}

function importProperties( schema ) {
	const out = {};
	for ( const c of schema.controls ) {
		for ( const property of c.import ?? [] ) out[ property ] = c.id;
	}
	return out;
}

function stateKeys( schema ) {
	return Object.fromEntries( Object.entries( schema.states ).map( ( [ id, s ] ) => [ id, s.key ] ) );
}

/** state → the pseudo-class selector it appends to an element ('' for default and ancestor states). */
function statePseudos( schema ) {
	return Object.fromEntries( Object.entries( schema.states ).map( ( [ id, s ] ) => [ id, s.pseudo ] ) );
}

/**
 * States selected by an ANCESTOR rather than by the element: `group` plays when the nearest card
 * around the element is pointed at or focused. `on` is the active ancestor, `off` an inactive one —
 * the second is what keeps an outer card from playing an inner card's children.
 */
/**
 * States selected by a MEDIA query rather than a selector: `reduced` plays when the visitor asked
 * for less motion. The element keeps its own class; the rule sits inside the query.
 */
function stateMedia( schema ) {
	return Object.fromEntries( Object.entries( schema.states ).filter( ( [ , s ] ) => s.media ).map( ( [ id, s ] ) => [ id, s.media ] ) );
}

/** state → the control ids it may style, for the states `stateControls` limits. Globs expanded. */
function stateControls( schema ) {
	const ids = schema.controls.map( ( c ) => c.id );
	const match = ( glob ) => ( glob.endsWith( '.*' ) ? ids.filter( ( id ) => id.startsWith( glob.slice( 0, -1 ) ) ) : ids.filter( ( id ) => id === glob ) );
	return Object.fromEntries( Object.entries( schema.stateControls ?? {} ).filter( ( [ id ] ) => ! id.startsWith( '$' ) ).map( ( [ state, globs ] ) => {
		if ( ! schema.states[ state ] ) throw new Error( `stateControls: "${ state }" is not a state` );
		return [ state, [ ...new Set( globs.flatMap( match ) ) ] ];
	} ) );
}

/**
 * Every engine variable a base consumer class reads. Registered `inherits: false` in runtime.scss:
 * a block with only a state value (a focus shadow) still carries the base class, and without this
 * its `var(--bl-bsh, none)` would pick up the value its parent card set. Nothing reads an engine
 * variable from another element, so nothing loses by it.
 */
function baseVars( schema ) {
	const letters = { sides: [ 't', 'r', 'b', 'l' ], corners: [ 'tl', 'tr', 'br', 'bl' ] };
	const out = new Set();
	for ( const c of schema.controls ) {
		if ( ! c.var ) continue;
		if ( c.kind === 'single' ) out.add( c.var.startsWith( '--' ) ? c.var : `--bl-${ c.var }` );
		else if ( c.kind === 'sides' ) letters.sides.forEach( ( l ) => out.add( `--bl-${ c.var }${ l }` ) );
		else if ( c.kind === 'corners' ) letters.corners.forEach( ( l ) => out.add( `--bl-${ c.var }${ l }` ) );
		else if ( c.kind === 'inset' ) letters.sides.forEach( ( l ) => out.add( `--bl-${ c.var }-${ l }` ) );
	}
	return [ ...out ].sort();
}

function stateAncestors( schema ) {
	return Object.fromEntries( Object.entries( schema.states ).filter( ( [ , s ] ) => s.ancestor ).map( ( [ id, s ] ) => [ id, { on: s.ancestor.on, off: s.ancestor.off } ] ) );
}

// ── TypeScript ───────────────────────────────────────────────────────────────

function renderTs( schema, breakpoints ) {
	const part = partTables( schema, breakpoints );
	const json = ( v ) => JSON.stringify( v, null, '\t' );
	return `// ${ HEADER }

/** One control's emission rule. See \`StyleMapRule\` in framework/css/vars.ts for each field. */
export interface EngineRule {
	attr: string;
	cls: string;
	kind: 'sides' | 'inset' | 'corners' | 'single' | 'enum';
	v: string;
	category?: string;
	raw?: boolean;
	emptyValue?: string;
	prop?: string;
	selectorSuffix?: string;
	/** Renders only on a part; a value in an element slot emits nothing. */
	partOnly?: boolean;
}

/** How a control's value is written on a part. \`guard\` mirrors a wrapper runtime.scss puts round it. */
export interface PartProp {
	prop: string;
	webkit?: boolean;
	guard?: 'motion' | 'timeline';
}

/** state → marker/var key (default has no key). */
export const STATE_KEY: Record< string, string > = ${ json( stateKeys( schema ) ) };

/** state → the pseudo-class selector it appends to an element ('' for default and ancestor states). */
export const STATE_PSEUDO: Record< string, string > = ${ json( statePseudos( schema ) ) };

/** state → the ancestor selectors that turn it on and off, for a state an ancestor selects. */
export const STATE_ANCESTOR: Record< string, { on: string; off: string } > = ${ json( stateAncestors( schema ) ) };

/** state → the control ids it may style, for a state limited to what it is for. Absent = every control. */
export const STATE_CONTROLS: Record< string, string[] > = ${ json( stateControls( schema ) ) };

/** state → the media query it plays under, for a state the visitor's settings select. */
export const STATE_MEDIA: Record< string, string > = ${ json( stateMedia( schema ) ) };

/** breakpoint id → marker/var key (base has no key). */
export const BP_KEY: Record< string, string > = ${ json( schema.breakpoints ) };

export const SIDES: Array< [ 'top' | 'right' | 'bottom' | 'left', string ] > = ${ JSON.stringify( schema.sides ) };

export const CORNERS: Array< [ 'topLeft' | 'topRight' | 'bottomRight' | 'bottomLeft', string ] > = ${ JSON.stringify( schema.corners ) };

/** Every built-in control, in emission order. */
export const RULES: readonly EngineRule[] = [
${ schema.controls.map( ( c ) => `\t${ JSON.stringify( rule( c ) ) },` ).join( '\n' ) }
];

/** Inspector facet id → the control ids it owns (drives allow-list, Reset and the "styled" dot). */
export const SECTION_CONTROLS: Record< string, readonly string[] > = ${ json( sectionControls( schema ) ) };

/** Part id → the pseudo-element it styles. The element itself is the implicit \`element\` part. */
export const PARTS: Record< string, string > = ${ json( schema.parts ?? {} ) };

/** \`cls\` → the property a part rule writes, for every control with a one-property runtime rule. */
export const PART_PROPS: Record< string, PartProp > = ${ json( part.props ) };

/** \`cls\` of the controls a part renders with bespoke code (inset, line clamp, clip-to-text). */
export const PART_SPECIAL: readonly string[] = ${ JSON.stringify( part.special ) };

/** Every control a part can render — what the inspector may offer while a part is selected. */
export const PART_CONTROLS: readonly string[] = ${ json( part.controls ) };

/** Breakpoint key → its max-width, for scoped part rules (the static tiers read \`$breakpoints\`). */
export const BP_MAX: Record< string, string > = ${ json( part.bpMax ) };

/** Breakpoint keys, widest first — the order scoped rules are emitted in so narrower ones win. */
export const BP_ORDER: readonly string[] = ${ JSON.stringify( part.bpOrder ) };

/** Type-role slugs, in picker order. Each is a global \`bl-type--{role}\` class in the runtime. */
export const TYPE_ROLES = ${ JSON.stringify( schema.typeRoles ) } as const;

/** A pasted CSS property → the control the importer maps it to. */
export const IMPORT_PROPERTIES: Record< string, string > = ${ json( importProperties( schema ) ) };

/** Controls that work but deserve a warning (\`caution\`) or sit behind search (\`niche\`). */
export const CONTROL_FLAGS: Record< string, 'caution' | 'niche' > = ${ json( Object.fromEntries( schema.controls.filter( ( c ) => c.flag ).map( ( c ) => [ c.id, c.flag ] ) ) ) };

export type RelationKind = ${ RELATION_KINDS.map( ( k ) => `'${ k }'` ).join( ' | ' ) };

/** How controls bear on one another. See RELATION_KINDS in scripts/gen-engine.mjs. */
export const RELATIONS: ReadonlyArray< { kind: RelationKind; from: string; to: readonly string[]; note: string } > = [
${ ( schema.relations ?? [] ).map( ( r ) => `\t${ JSON.stringify( r ) },` ).join( '\n' ) }
];

/** JSON Schema for each kind of value a control takes. See valueShapeOf() in scripts/gen-engine.mjs. */
export const VALUE_SHAPES: Record< string, Record< string, unknown > > = ${ json( resolvedShapes( schema ) ) };

/** Each control's value shape, token scale and (for an enum) accepted names. */
export const CONTROL_VALUES: Record< string, { shape: string; tokens?: string; values?: readonly string[]; property?: string; note?: string } > = ${ json( Object.fromEntries( schema.controls.map( ( c ) => [ c.id, valueShapeOf( c, schema ) ] ) ) ) };

/** How a control's values are stored: per state, then per breakpoint. */
export const VALUE_TREE: Record< string, unknown > = ${ json( schema.valueTree ?? {} ) };
`;
}

// ── PHP ──────────────────────────────────────────────────────────────────────

function phpValue( v, indent ) {
	const pad = '\t'.repeat( indent );
	if ( typeof v === 'string' ) return `'${ v.replace( /\\/g, '\\\\' ).replace( /'/g, "\\'" ) }'`;
	if ( typeof v === 'boolean' ) return v ? 'true' : 'false';
	if ( typeof v === 'number' ) return String( v );
	if ( Array.isArray( v ) ) {
		if ( v.every( ( x ) => typeof x !== 'object' ) ) return `[ ${ v.map( ( x ) => phpValue( x, 0 ) ).join( ', ' ) } ]`;
		return `[\n${ v.map( ( x ) => `${ pad }\t${ phpValue( x, indent + 1 ) },` ).join( '\n' ) }\n${ pad }]`;
	}
	const entries = Object.entries( v );
	if ( ! entries.length ) return '[]';
	return `[\n${ entries.map( ( [ k, x ] ) => `${ pad }\t'${ k }' => ${ phpValue( x, indent + 1 ) },` ).join( '\n' ) }\n${ pad }]`;
}

function renderPhp( schema, breakpoints ) {
	const part = partTables( schema, breakpoints );
	return `<?php
/**
 * ${ HEADER }
 *
 * @package Blicks
 */

declare(strict_types=1);

namespace Blicks\\Style;

defined( 'ABSPATH' ) || exit;

/**
 * The style engine's tables, as {@see ElementStyle} reads them. The same data feeds the editor's
 * engine (resources/engine/schema.gen.ts) and the runtime stylesheet (resources/runtime/_engine.scss).
 *
 * @internal Not part of the extension API — use {@see EngineSchema::describe()} or {@see ElementStyle::controls()}.
 */
final class Schema {

	/** State → marker/var key (default has no key). */
	public const STATE_KEY = ${ phpValue( stateKeys( schema ), 1 ) };

	/** State → the pseudo-class selector it appends to an element ('' for default and ancestor states). */
	public const STATE_PSEUDO = ${ phpValue( statePseudos( schema ), 1 ) };

	/** State → the ancestor selectors that turn it on and off, for a state an ancestor selects. */
	public const STATE_ANCESTOR = ${ phpValue( stateAncestors( schema ), 1 ) };

	/** State → the control ids it may style, for a state limited to what it is for. Absent = every control. */
	public const STATE_CONTROLS = ${ phpValue( stateControls( schema ), 1 ) };

	/** State → the media query it plays under, for a state the visitor's settings select. */
	public const STATE_MEDIA = ${ phpValue( stateMedia( schema ), 1 ) };

	/** Breakpoint id → marker/var key (base has no key). */
	public const BP_KEY = ${ phpValue( schema.breakpoints, 1 ) };

	/** [side-key, var-suffix] */
	public const SIDES = ${ phpValue( schema.sides, 1 ) };

	/** [corner-key, var-suffix] */
	public const CORNERS = ${ phpValue( schema.corners, 1 ) };

	/** Part id → the pseudo-element it styles. */
	public const PARTS = ${ phpValue( schema.parts ?? {}, 1 ) };

	/** \`cls\` → how a part rule writes the control: prop, plus optional webkit twin and guard. */
	public const PART_PROPS = ${ phpValue( part.props, 1 ) };

	/** \`cls\` of the controls a part renders with bespoke code. */
	public const PART_SPECIAL = ${ phpValue( part.special, 1 ) };

	/** Breakpoint key → max-width, for scoped part rules. */
	public const BP_MAX = ${ phpValue( part.bpMax, 1 ) };

	/** Breakpoint keys, widest first. */
	public const BP_ORDER = ${ phpValue( part.bpOrder, 1 ) };

	/** Type-role slugs, in picker order. */
	public const TYPE_ROLES = ${ phpValue( schema.typeRoles, 1 ) };

	/** Every built-in control, in emission order. */
	public const RULES = ${ phpValue( schema.controls.map( rule ), 1 ) };

	/** Inspector section id → the control ids it owns. Read by EngineSchema::describe(). */
	public const SECTION_CONTROLS = ${ phpValue( sectionControls( schema ), 1 ) };

	/** Every control a part (\`::before\`/\`::after\`) can render. */
	public const PART_CONTROLS = ${ phpValue( part.controls, 1 ) };

	/** Controls that work but deserve a warning (\`caution\`) or sit behind search (\`niche\`). */
	public const CONTROL_FLAGS = ${ phpValue( Object.fromEntries( schema.controls.filter( ( c ) => c.flag ).map( ( c ) => [ c.id, c.flag ] ) ), 1 ) };

	/** How controls bear on one another — kinds are documented in scripts/gen-engine.mjs. */
	public const RELATIONS = ${ phpValue( schema.relations ?? [], 1 ) };

	/** JSON Schema for each kind of value a control takes. See valueShapeOf() in scripts/gen-engine.mjs. */
	public const VALUE_SHAPES = ${ phpValue( resolvedShapes( schema ), 1 ) };

	/** Each control's value shape, token scale and (for an enum) accepted names. */
	public const CONTROL_VALUES = ${ phpValue( Object.fromEntries( schema.controls.map( ( c ) => [ c.id, valueShapeOf( c, schema ) ] ) ), 1 ) };

	/** How a control's values are stored: per state, then per breakpoint. */
	public const VALUE_TREE = ${ phpValue( schema.valueTree ?? {}, 1 ) };
}
`;
}

// ── SCSS ─────────────────────────────────────────────────────────────────────

function scssMap( name, entries ) {
	const body = entries.map( ( [ key, cfg ] ) => `\t'${ key }': ( ${ cfg } ),` ).join( '\n' );
	return `$${ name }: (\n${ body }\n);\n`;
}

function renderScss( schema, breakpoints ) {
	const groups = Object.fromEntries( Object.keys( SCSS_MAPS ).map( ( g ) => [ g, [] ] ) );

	for ( const c of schema.controls ) {
		const rt = c.runtime;
		if ( ! rt || ! groups[ rt.group ] ) continue;
		let cfg;
		if ( rt.group === 'spacing' ) {
			cfg = `prop: ${ rt.prop }, v: '${ c.var }'`;
		} else if ( rt.group === 'multi' ) {
			const letters = ( c.kind === 'corners' ? schema.corners : schema.sides ).map( ( [ , l ] ) => `'${ c.var }${ l }'` );
			cfg = `prop: ${ rt.prop }, vars: (${ letters.join( ', ' ) }), fallback: ${ rt.fallback }`;
			// Corners are written as four longhands: a corner may hold two values (an elliptical
			// `255px 15px`), which the `border-radius` shorthand only accepts in its slash form.
			if ( c.kind === 'corners' ) cfg += `, longhands: (${ cornerLonghands( rt.prop ).join( ', ' ) })`;
		} else if ( rt.group === 'supports' ) {
			cfg = `prop: ${ rt.prop }, guard: '${ rt.guard }', webkit: ${ rt.webkit ? 'true' : 'false' }`;
		} else {
			cfg = `prop: ${ rt.prop }, default: ${ rt.default }`;
			if ( rt.group === 'gridChild' ) cfg += `, span: ${ rt.span ? 'true' : 'false' }`;
		}
		groups[ rt.group ].push( [ c.cls, cfg ] );
	}

	const bpEntries = breakpoints.map( ( bp ) => {
		const key = schema.breakpoints[ bp.id ];
		if ( key === undefined ) throw new Error( `${ BREAKPOINTS }: breakpoint "${ bp.id }" has no key in ${ SCHEMA }` );
		return `'${ key || 'base' }': ${ bp.max === null ? 'null' : `${ bp.max }px` }`;
	} );
	const stateEntries = Object.values( schema.states ).map( ( s ) => `'${ s.key }': '${ s.pseudo }'` );

	return `// ${ HEADER }
// Breakpoint widths come from ${ BREAKPOINTS }.

$breakpoints: ( ${ bpEntries.join( ', ' ) } );
$states: ( ${ stateEntries.join( ', ' ) } );
$state-controls: ( ${ Object.entries( stateControls( schema ) ).map( ( [ id, list ] ) => `'${ schema.states[ id ].key }': ( ${ list.map( ( c ) => { const rule = schema.controls.find( ( r ) => r.id === c ); return `'${ rule.cls }'`; } ).join( ', ' ) }, )` ).join( ', ' ) } );
$base-vars: ( ${ baseVars( schema ).map( ( v ) => `'${ v }'` ).join( ', ' ) } );
$state-media: ( ${ Object.entries( stateMedia( schema ) ).map( ( [ id, q ] ) => `'${ schema.states[ id ].key }': '${ q }'` ).join( ', ' ) } );
$state-ancestors: ( ${ Object.entries( stateAncestors( schema ) ).map( ( [ id, a ] ) => `'${ schema.states[ id ].key }': ( on: '${ a.on }', off: '${ a.off }' )` ).join( ', ' ) } );
$type-roles: ${ schema.typeRoles.join( ', ' ) };

${ Object.entries( SCSS_MAPS ).map( ( [ g, name ] ) => scssMap( name, groups[ g ] ) ).join( '\n' ) }`;
}

// ── Entry ────────────────────────────────────────────────────────────────────

/** Every generated file's path and content, from the schema on disk. */
export function render() {
	const schema = read( SCHEMA );
	const breakpoints = read( BREAKPOINTS );
	validate( schema );
	return {
		[ OUTPUTS.ts ]: renderTs( schema, breakpoints ),
		[ OUTPUTS.php ]: renderPhp( schema, breakpoints ),
		[ OUTPUTS.scss ]: renderScss( schema, breakpoints ),
	};
}

/** Paths whose content on disk differs from what the schema generates. */
export function stale() {
	return Object.entries( render() )
		.filter( ( [ file, content ] ) => {
			const abs = path.join( root, file );
			return ! fs.existsSync( abs ) || fs.readFileSync( abs, 'utf8' ) !== content;
		} )
		.map( ( [ file ] ) => file );
}

if ( process.argv[ 1 ] && path.resolve( process.argv[ 1 ] ) === fileURLToPath( import.meta.url ) ) {
	if ( process.argv.includes( '--check' ) ) {
		const files = stale();
		if ( files.length ) {
			console.error( `✗ Generated engine files are stale — run \`pnpm gen:engine\`:\n  ${ files.join( '\n  ' ) }` );
			process.exit( 1 );
		}
		console.log( '✓ Generated engine files match the schema.' );
	} else {
		for ( const [ file, content ] of Object.entries( render() ) ) {
			fs.writeFileSync( path.join( root, file ), content );
			console.log( `wrote ${ file }` );
		}
	}
}
